// Everywhere else:  client asks → server answers → connection closes
// Chat:             message arrives → server must PUSH to a device
//
// → WebSocket (fallback: long polling where it's blocked)
// → the connection lives on ONE machine → the tier is stateful

const TTL = 45;   // seconds; heartbeat refreshes well inside it

async function onConnect(userId, serverId) {
  await redis.set(`conn:${userId}`, serverId, { EX: TTL });
}

async function onHeartbeat(userId, serverId) {
  await redis.expire(`conn:${userId}`, TTL);   // still alive
}

// No explicit cleanup path needed for an ungraceful drop —
// the key simply expires, which is why a TTL beats a delete.

async function onSend(fromId, conversationId, body, idempotencyKey) {
  const existing = await db.messages.byKey(idempotencyKey);
  if (existing) return existing;               // retry — not a new message

  const messageId = await ids.next();          // server-side, ~time-sortable
  const msg = { messageId, conversationId, fromId, body, at: Date.now() };

  await db.messages.insert(msg);               // durable BEFORE delivery
  await deliver(conversationId, msg);
  return msg;
}

async function deliver(conversationId, msg) {
  const members = await db.conversations.members(conversationId);

  await Promise.all(members.map(async (uid) => {
    if (uid === msg.fromId) return;

    const serverId = await redis.get(`conn:${uid}`);
    if (serverId) return rpc(serverId).push(uid, msg);   // internal hop

    return push.notify(uid, msg);   // offline: already stored, just nudge
  }));
}

async function onReconnect(userId, deviceId) {
  const cursors = await db.cursors.forDevice(deviceId);   // per conversation

  return Promise.all(cursors.map(({ conversationId, lastSeenId }) =>
    db.messages.after(conversationId, lastSeenId, 500)
  ));
}

async function onAck(deviceId, conversationId, messageId) {
  await db.cursors.advance(deviceId, conversationId, messageId);
}

// Client generates the key at compose time, reuses it across retries:
//   const key = `${deviceId}:${localCounter++}`;
//
// Server side, the check must be ATOMIC with the insert or two
// concurrent retries both pass it:
await db.messages.insertIfAbsent({ idempotencyKey: key, ...msg });

// Exactly-once delivery isn't achievable end to end.
// At-least-once + idempotency is observably the same thing.

const PUSH_LIMIT = 500;

async function deliverGroup(conversationId, msg) {
  const members = await db.conversations.members(conversationId);

  if (members.length <= PUSH_LIMIT) return deliver(conversationId, msg);

  // large group: store once, signal cheaply, let clients pull by cursor
  return rpc.broadcastChanged(conversationId);
}

// server: stop accepting new connections, let existing ones migrate
async function drain(server) {
  server.rejectNewConnections();
  await server.notifyClientsToMigrate();
  await sleep(30_000);
}

// client: never reconnect on a fixed schedule
const backoff = (n) => Math.min(30_000, 2 ** n * 500) * (0.5 + Math.random());
